import {speakingTopics as topics} from './practice-library.js';
import {createPronunciation} from './pronunciation.js';
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let answerMode='both',textScale=1;
const modelAudio=createPronunciation({getPreferences:()=>({accent:'en-GB',rate:0.9}),onError:message=>{if(document.querySelector('#model-status'))document.querySelector('#model-status').textContent=message;}});
let selected=0,recorder=null,stream=null,timer=null,seconds=0,phase='idle',recordingUrl='',recordingType='',error='',starting=false,generation=0;
const $=s=>document.querySelector(s),clock=n=>`${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;
export function speakingView(){const t=topics[selected];return `<div class="page-heading"><div><span class="eyebrow">OG‘ZAKI MASHQ</span><h1>Speaking</h1><p>A1 dan C1 gacha: savol, namuna va o‘z javobingiz.</p></div><span class="pill">Shaxsiy mashq</span></div><div class="speaking-layout"><section class="panel"><label>Mashq turi<select class="speaking-type" id="speaking-type" ${phase==='recording'||starting?'disabled':''}>${topics.map((x,i)=>`<option value="${i}" ${selected===i?'selected':''}>${x.level} · ${x.type}</option>`).join('')}</select></label><div class="speaking-tools"><label>Ko‘rinish<select id="speaking-mode"><option value="both">Savol va javob</option><option value="question">Faqat savol</option></select></label><label>Matn o‘lchami<select id="speaking-zoom"><option value="1">100%</option><option value="1.2">120%</option><option value="1.4">140%</option></select></label></div><div class="recording-stage" id="speaking-area" style="font-size:${textScale}rem"><span class="prompt-tag">YOUR QUESTION</span><h2>${t.title}</h2><section id="speaking-model" ${answerMode==='question'?'hidden':''}><span class="eyebrow">NAMUNA · O‘Z JAVOBINGIZGA MOSLANG</span><p class="model-answer">${escape(t.answer).replace(escape(t.mark),'<mark>'+escape(t.mark)+'</mark>')}</p><button class="btn" id="model-listen">Namunani tinglash</button><p id="model-status" role="status"></p><details><summary>Grammatika va iboralar</summary><p><b>Grammar:</b> ${escape(t.grammar)}</p><p><b>Vocabulary:</b> ${escape(t.vocab)}</p></details></section><div id="recorder-controls">${controls()}</div></div></section><aside><section class="panel"><span class="eyebrow">JAVOBNI TUZISH UCHUN</span><h2>Nimalarni aytish mumkin?</h2><ul class="prompt-help">${t.points.map(p=>`<li>${p}</li>`).join('')}</ul><div class="quiet-note">Javobni avval qisqa rejalashtiring. Tayyor matnni o‘qishdan ko‘ra, fikringizni o‘z so‘zlaringiz bilan aytishga harakat qiling.</div></section><div class="quiet-note"><b>Yozuv shu sessiyada qoladi.</b><br>Ovoz serverga yuborilmaydi. Saqlab qolish uchun audio faylni yuklab oling. Sahifani yopish yoki yangilash yozuvni yo‘qotadi.</div><div class="notice">Ustozga topshirish va avtomatik baholash hali ulanmagan. Bu mashq uchun XP yoki IELTS band bahosi berilmaydi.</div></aside></div>`;}
function controls(){return `<div class="recording-clock" id="recording-clock">${clock(seconds)}</div><p id="recording-status">${starting?'Mikrofonga ruxsat kutilmoqda…':phase==='recording'?'<span class="recording-light"></span>Ovoz yozilyapti':phase==='ready'?'Javobingizni tinglab, o‘zingiz baholang.':'Tayyor bo‘lgach yozishni boshlang.'}</p>${recordingUrl?`<audio controls src="${recordingUrl}"></audio>`:''}<div class="buttons">${phase==='recording'?'<button type="button" class="btn primary" id="record-stop">To‘xtatish</button>':`<button type="button" class="btn primary" id="record-start" ${starting?'disabled':''}>${recordingUrl?'Yangi urinish':'Ovoz yozish'}</button>`}${recordingUrl&&phase!=='recording'?`<a class="btn" href="${recordingUrl}" download="lexora-speaking.${recordingType.includes('mp4')?'m4a':recordingType.includes('ogg')?'ogg':'webm'}">Audioni saqlash ↓</a><button type="button" class="text-btn" id="record-delete">Yozuvni o‘chirish</button>`:''}</div><p class="error" id="recording-error">${error}</p>`;}
function update(){if(!$('#recorder-controls'))return;$('#recorder-controls').innerHTML=controls();bind();if($('#speaking-type'))$('#speaking-type').disabled=phase==='recording'||starting;}
function release(){clearInterval(timer);timer=null;stream?.getTracks().forEach(t=>t.stop());stream=null;}
function stop(){if(recorder?.state==='recording')recorder.stop();release();}
async function start(){modelAudio.stop();if(starting||phase==='recording')return;if(recordingUrl&&!window.confirm('Yangi urinish oldingi yozuvni almashtiradi. Davom etasizmi?'))return;
 const attempt=++generation;starting=true;error='';update();
 try {
  if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)throw new Error('unsupported');
  const input=await navigator.mediaDevices.getUserMedia({audio:true});
  if(attempt!==generation||!$('#speaking-area')){input.getTracks().forEach(t=>t.stop());return;}
  stream=input;
  const mime=['audio/webm;codecs=opus','audio/mp4','audio/ogg;codecs=opus'].find(t=>MediaRecorder.isTypeSupported(t));
  recorder=new MediaRecorder(stream,mime?{mimeType:mime}:undefined);
  const chunks=[];
  recorder.ondataavailable=ev=>{if(ev.data.size)chunks.push(ev.data);};
  recorder.onstop=()=>{release();if(attempt!==generation)return;const blob=new Blob(chunks,{type:recorder.mimeType});if(recordingUrl)URL.revokeObjectURL(recordingUrl);recordingType=blob.type;recordingUrl=blob.size?URL.createObjectURL(blob):'';phase=recordingUrl?'ready':'idle';if(!blob.size)error='Ovoz yozilmadi. Mikrofonni tekshirib qayta urinib ko‘ring.';update();};
  recorder.onerror=()=>{error='Yozishda xato bo‘ldi. Mikrofonni tekshiring.';stop();};
  recorder.start();seconds=0;phase='recording';starting=false;update();const started=Date.now();
  timer=setInterval(()=>{seconds=Math.min(topics[selected].seconds,Math.floor((Date.now()-started)/1000));if($('#recording-clock'))$('#recording-clock').textContent=clock(seconds);if(seconds>=topics[selected].seconds)stop();},250);
 }catch(err){if(attempt!==generation)return;release();phase=recordingUrl?'ready':'idle';error=err.message==='unsupported'?'Bu brauzer ovoz yozishni qo‘llamaydi. Yangilangan Chrome, Edge yoki Safari’dan foydalaning.':err.name==='NotAllowedError'?'Mikrofonga ruxsat berilmadi. Brauzer sozlamasida ruxsatni yoqib, qayta urinib ko‘ring.':'Mikrofon topilmadi yoki boshqa dastur ishlatyapti.';}
 finally{if(attempt===generation){starting=false;update();}}
}
function bind(){$('#record-start')?.addEventListener('click',start);$('#record-stop')?.addEventListener('click',stop);$('#record-delete')?.addEventListener('click',()=>{if(recordingUrl)URL.revokeObjectURL(recordingUrl);recordingUrl='';phase='idle';seconds=0;error='';update();});}
export function mountSpeaking(){bind();$('#speaking-mode').value=answerMode;$('#speaking-zoom').value=String(textScale);$('#speaking-mode').onchange=ev=>{answerMode=ev.target.value;$('#speaking-model').hidden=answerMode==='question';if(answerMode==='question')modelAudio.stop();};$('#speaking-zoom').onchange=ev=>{textScale=Number(ev.target.value);$('#speaking-area').style.fontSize=textScale+'rem';};$('#model-listen').onclick=()=>modelAudio.speak(topics[selected].answer);$('#speaking-type').onchange=ev=>{if(recordingUrl){ev.target.value=String(selected);error='Boshqa mashqni tanlashdan oldin yozuvni saqlang yoki o‘chiring.';update();return;}selected=Number(ev.target.value);seconds=0;error='';const app=$('#app');app.innerHTML=speakingView();mountSpeaking();};}
export function leaveSpeaking(){modelAudio.stop();if(starting){generation++;starting=false;}stop();}
window.addEventListener('pagehide',()=>{generation++;release();if(recorder?.state==='recording')recorder.stop();if(recordingUrl)URL.revokeObjectURL(recordingUrl);});
